import sys

from . import extract_headings, render_toc, update_toc


def _parse_int(flag: str, args: list[str]) -> int | None:
    """Extract *flag* value from *args*, removing both from the list."""
    if flag in args:
        idx = args.index(flag)
        if idx + 1 >= len(args):
            print(f"{flag} requires a value", file=sys.stderr)
            sys.exit(2)
        try:
            return int(args[idx + 1])
        except ValueError:
            print(f"{flag} value must be an integer", file=sys.stderr)
            sys.exit(2)
        del args[idx:idx + 2]
    return None


def main() -> None:
    args = sys.argv[1:]
    write = False
    if "--write" in args:
        write = True
        args.remove("--write")

    min_level = _parse_int("--min-level", args)
    max_level = _parse_int("--max-level", args)

    if len(args) != 1:
        print("usage: python3 -m mdtoc [--write] [--min-level N] [--max-level N] FILE",
              file=sys.stderr)
        sys.exit(2)

    path = args[0]
    with open(path, encoding="utf-8") as f:
        text = f.read()

